# Searches this database's records by name or meaning.
RECORD = {
    "id": "JAH-NMMNC-000001",
    "name": "Ah-hui 阿輝",
    "kind": "first-name",
    "meaning": "Ah-hui (阿輝) is a masculine given name in Min Nan Chinese. Meaning: Radiance. The Ah- prefix marks affectionate address."
}
ARCHIVE = [RECORD]  # extend: load the full archive from index.jsonl.gz to search all records
def lookup(query):
    q = query.strip().lower()
    return [r for r in ARCHIVE if q in r['name'].lower() or q in r['meaning'].lower()]
if __name__ == '__main__':
    hits = lookup("Ah-")
    for h in hits:
        print(h['id'], '|', h['name'], '|', h['meaning'])

